import sys
from functools import lru_cache

data = sys.stdin.read().split()
n = int(data[0])
a = tuple(map(int, data[1:1 + n]))

@lru_cache(maxsize=None)
def solve(t):
    if len(t) == 0:
        return 0
    if len(t) < 3:
        return max(t)
    best = None
    for i, j in ((0, 1), (0, 2), (1, 2)):
        rest = tuple(t[k] for k in range(len(t)) if k != i and k != j)
        c = max(t[i], t[j]) + solve(rest)
        if best is None or c < best:
            best = c
    return best

print(solve(a))

